gX4(){return"\u0646\u0645\u0648\u0648\u0646\u06d5: \u0661\u0661\u060c \u0661\u0662\u060c \u0662\u0664\u060c \u0664\u0666"},
gXp(){return"\u0646\u0645\u0648\u0648\u0646\u06d5: UR1\u060c UR2\u060c UL4\u060c LR6"},
